def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re
    import sys

    token_pattern = re.compile(r"[0-9]+|[A-Z]+[0-9]*|<>|<=|>=|[+\-*/(),:=<>]")
    values = {}
    active = set()

    def integer(text):
        negative = text.startswith("-")
        if negative:
            text = text[1:]
        result = 0
        for i in range(0, len(text), 9):
            chunk = text[i:i + 9]
            result = result * (10 ** len(chunk)) + int(chunk)
        return -result if negative else result

    def parse(content):
        if not content.startswith("="):
            return ("number", integer(content))

        tokens = token_pattern.findall(content[1:])
        required_limit = len(tokens) * 8 + 1000
        if required_limit > sys.getrecursionlimit():
            sys.setrecursionlimit(required_limit)
        pos = 0

        def expression():
            nonlocal pos
            node = term()
            while pos < len(tokens) and tokens[pos] in ("+", "-"):
                op = tokens[pos]
                pos += 1
                node = ("binary", op, node, term())
            return node

        def term():
            nonlocal pos
            node = unary()
            while pos < len(tokens) and tokens[pos] in ("*", "/"):
                op = tokens[pos]
                pos += 1
                node = ("binary", op, node, unary())
            return node

        def unary():
            nonlocal pos
            negate = False
            while pos < len(tokens) and tokens[pos] == "-":
                negate = not negate
                pos += 1
            node = atom()
            return ("negate", node) if negate else node

        def atom():
            nonlocal pos
            token = tokens[pos]
            pos += 1

            if token == "(":
                node = expression()
                pos += 1  # )
                return node

            if token[0].isdigit():
                return ("number", integer(token))

            if token not in ("SUM", "MIN", "MAX", "IF"):
                return ("reference", token)

            pos += 1  # (
            if token == "IF":
                left = expression()
                op = tokens[pos]
                pos += 1
                right = expression()
                pos += 1  # ,
                then_branch = expression()
                pos += 1  # ,
                else_branch = expression()
                pos += 1  # )
                return ("if", op, left, right, then_branch, else_branch)

            args = []
            while True:
                if (
                    pos + 1 < len(tokens)
                    and tokens[pos][0].isalpha()
                    and tokens[pos + 1] == ":"
                ):
                    args.append(("range", tokens[pos], tokens[pos + 2]))
                    pos += 3
                else:
                    args.append(expression())

                if tokens[pos] == ")":
                    pos += 1
                    break
                pos += 1  # ,
            return ("function", token, args)

        return expression()

    def function_items(args):
        for arg in args:
            if arg[0] != "range":
                yield arg
                continue

            first, last = arg[1], arg[2]
            left, right = sorted((ord(first[0]), ord(last[0])))
            top, bottom = sorted((int(first[1:]), int(last[1:])))
            for row in range(top, bottom + 1):
                for column in range(left, right + 1):
                    name = chr(column) + str(row)
                    if name in cells:
                        yield ("reference", name)

    def evaluate(start):
        results = []
        tasks = [("reference", start)]

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "reference":
                name = task[1]
                if name in values:
                    results.append(values[name])
                elif name not in cells:
                    results.append(0)
                elif name in active:
                    results.append("#CYCLE!")
                else:
                    active.add(name)
                    tasks.append(("finish_cell", name))
                    tasks.append(("evaluate", parse(cells[name])))

            elif kind == "finish_cell":
                name = task[1]
                active.remove(name)
                values[name] = results[-1]

            elif kind == "evaluate":
                node = task[1]
                node_kind = node[0]

                if node_kind == "number":
                    results.append(node[1])
                elif node_kind == "reference":
                    tasks.append(("reference", node[1]))
                elif node_kind == "negate":
                    tasks.append(("negate",))
                    tasks.append(("evaluate", node[1]))
                elif node_kind == "binary":
                    tasks.append(("binary_left", node[1], node[3]))
                    tasks.append(("evaluate", node[2]))
                elif node_kind == "if":
                    tasks.append(("if_left", node))
                    tasks.append(("evaluate", node[2]))
                else:
                    tasks.append(
                        ("function_next", node[1], iter(function_items(node[2])), None)
                    )

            elif kind == "negate":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("evaluate", task[2]))

            elif kind == "binary_right":
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                    continue

                op, left = task[1], task[2]
                if op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif right == 0:
                    results.append("#DIV/0!")
                else:
                    quotient = abs(left) // abs(right)
                    results.append(-quotient if (left < 0) != (right < 0) else quotient)

            elif kind == "if_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    node = task[1]
                    tasks.append(("if_right", node, left))
                    tasks.append(("evaluate", node[3]))

            elif kind == "if_right":
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                    continue

                node, left = task[1], task[2]
                op = node[1]
                if op == "=":
                    condition = left == right
                elif op == "<>":
                    condition = left != right
                elif op == "<":
                    condition = left < right
                elif op == "<=":
                    condition = left <= right
                elif op == ">":
                    condition = left > right
                else:
                    condition = left >= right
                tasks.append(("evaluate", node[4] if condition else node[5]))

            elif kind == "function_next":
                name, items, aggregate = task[1:]
                item = next(items, None)
                if item is None:
                    results.append(0 if aggregate is None else aggregate)
                else:
                    tasks.append(("function_value", name, items, aggregate))
                    tasks.append(("evaluate", item))

            else:  # function_value
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                    continue

                name, items, aggregate = task[1:]
                if aggregate is None:
                    aggregate = value
                elif name == "SUM":
                    aggregate += value
                elif name == "MIN":
                    aggregate = min(aggregate, value)
                else:
                    aggregate = max(aggregate, value)
                tasks.append(("function_next", name, items, aggregate))

        return results.pop()

    for name in cells:
        if name not in values:
            evaluate(name)

    return {name: values[name] for name in cells}
